/*
 * Quire UI foundation: tokens, density and motion.
 * Import once after Tailwind: @import "tailwindcss"; @import "./quireui.css";
 * Every component reads from these variables, so restyling happens here, not per component.
 */

@custom-variant dark (&:where(.dark, .dark *));

/* Raw palette. Light steps are true greys so light mode reads as plain white; the dark
   steps keep a faint warmth, which is invisible as tint but softens large dark areas. */
:root {
  --qui-neutral-0: oklch(100% 0 0);
  --qui-neutral-25: oklch(98.8% 0 0);
  --qui-neutral-50: oklch(97.3% 0 0);
  --qui-neutral-100: oklch(95% 0 0);
  --qui-neutral-200: oklch(91% 0 0);
  --qui-neutral-300: oklch(85% 0 0);
  --qui-neutral-400: oklch(70% 0 0);
  --qui-neutral-500: oklch(56% 0 0);
  --qui-neutral-600: oklch(45% 0 0);
  --qui-neutral-700: oklch(35% 0.012 85);
  --qui-neutral-800: oklch(26% 0.01 85);
  --qui-neutral-850: oklch(22% 0.009 85);
  --qui-neutral-900: oklch(18.5% 0.008 85);
  --qui-neutral-950: oklch(14.5% 0.007 85);
  --qui-red-500: oklch(58% 0.19 30);
  --qui-red-400: oklch(66% 0.17 30);
  --qui-green-500: oklch(56% 0.12 155);
  --qui-green-400: oklch(72% 0.13 155);
  --qui-amber-500: oklch(64% 0.13 70);
  --qui-amber-400: oklch(78% 0.13 75);
  --qui-blue-500: oklch(56% 0.14 255);
  --qui-blue-400: oklch(72% 0.11 255);
}

/* Semantic tokens. Components only ever use these. */
:root {
  --qui-bg: var(--qui-neutral-0);
  --qui-surface: var(--qui-neutral-0);
  --qui-surface-muted: var(--qui-neutral-50);
  --qui-surface-hover: var(--qui-neutral-100);
  --qui-surface-active: var(--qui-neutral-200);
  /* Something raised out of a muted track, like the chosen segment. Lighter than the track in both themes. */
  --qui-surface-raised: var(--qui-neutral-0);
  --qui-fg: var(--qui-neutral-950);
  --qui-fg-muted: var(--qui-neutral-600);
  --qui-fg-subtle: var(--qui-neutral-500);
  --qui-border: var(--qui-neutral-200);
  --qui-border-strong: var(--qui-neutral-300);
  --qui-primary: var(--qui-neutral-900);
  --qui-primary-hover: var(--qui-neutral-800);
  --qui-primary-fg: var(--qui-neutral-25);
  --qui-danger: var(--qui-red-500);
  --qui-danger-fg: var(--qui-neutral-0);
  /* Status hues for badges and icons. Used as a tint or a mark, never as a large fill. */
  --qui-success: var(--qui-green-500);
  --qui-warning: var(--qui-amber-500);
  --qui-info: var(--qui-blue-500);
  --qui-ring: var(--qui-neutral-950);
  --qui-backdrop: oklch(14.5% 0 0 / 0.32);
  /* The only shadow in the system: floating layers need depth to separate from content. */
  --qui-shadow-float: 0 8px 24px -10px oklch(14.5% 0.007 85 / 0.18),
    0 2px 6px -2px oklch(14.5% 0.007 85 / 0.06);
  /* The start colour of scroll edges, the fade under a sticky part while content is beneath it. */
  --qui-edge: oklch(14.5% 0.007 85 / 0.04);
  /* Loading placeholders, and the faint light that sweeps across them. */
  --qui-skeleton: color-mix(in oklab, var(--qui-fg) 6%, var(--qui-surface));
  --qui-skeleton-sweep: oklch(100% 0 0 / 0.55);
}

.dark {
  --qui-bg: var(--qui-neutral-950);
  --qui-surface: var(--qui-neutral-900);
  --qui-surface-muted: var(--qui-neutral-900);
  --qui-surface-hover: var(--qui-neutral-850);
  --qui-surface-active: var(--qui-neutral-800);
  --qui-surface-raised: var(--qui-neutral-850);
  --qui-fg: var(--qui-neutral-50);
  --qui-fg-muted: var(--qui-neutral-400);
  --qui-fg-subtle: var(--qui-neutral-500);
  --qui-border: var(--qui-neutral-800);
  --qui-border-strong: var(--qui-neutral-700);
  --qui-primary: var(--qui-neutral-50);
  --qui-primary-hover: var(--qui-neutral-200);
  --qui-primary-fg: var(--qui-neutral-950);
  --qui-danger: var(--qui-red-400);
  --qui-success: var(--qui-green-400);
  --qui-warning: var(--qui-amber-400);
  --qui-info: var(--qui-blue-400);
  --qui-ring: var(--qui-neutral-50);
  --qui-backdrop: oklch(0% 0 0 / 0.6);
  --qui-shadow-float: 0 8px 24px -8px oklch(0% 0 0 / 0.6);
  --qui-edge: oklch(0% 0 0 / 0.28);
  --qui-skeleton: color-mix(in oklab, var(--qui-fg) 7%, var(--qui-surface));
  --qui-skeleton-sweep: oklch(100% 0 0 / 0.04);
  color-scheme: dark;
}

/* Density. Set data-density on any container; descendants resize without new classes. */
:root,
[data-density="default"] {
  --qui-control-h: 2rem;
  --qui-control-px: 0.75rem;
  --qui-item-h: 2rem;
  --qui-text: 0.875rem;
}
[data-density="compact"] {
  --qui-control-h: 1.75rem;
  --qui-control-px: 0.625rem;
  --qui-item-h: 1.75rem;
  --qui-text: 0.8125rem;
}
[data-density="comfortable"] {
  --qui-control-h: 2.5rem;
  --qui-control-px: 1rem;
  --qui-item-h: 2.25rem;
  --qui-text: 0.9375rem;
}
/* Touch needs real targets no matter the density. */
@media (pointer: coarse) {
  :root,
  [data-density] {
    --qui-control-h: 2.75rem;
    --qui-item-h: 2.75rem;
  }
}

/* Motion tokens. Nothing in the core goes above --qui-duration-slow. */
:root {
  --qui-duration-fast: 120ms;
  --qui-duration-base: 160ms;
  --qui-duration-slow: 220ms;
  /* Exits run at ~0.7x so dismissing never feels slower than opening. */
  --qui-duration-exit: 110ms;
  --qui-ease-out: cubic-bezier(0.2, 0.8, 0.2, 1);
  --qui-ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --qui-pop-scale: 0.96;
  --qui-pop-shift: 4px;
}

@theme inline {
  --color-bg: var(--qui-bg);
  --color-surface: var(--qui-surface);
  --color-surface-muted: var(--qui-surface-muted);
  --color-surface-hover: var(--qui-surface-hover);
  --color-surface-active: var(--qui-surface-active);
  --color-surface-raised: var(--qui-surface-raised);
  --color-fg: var(--qui-fg);
  --color-fg-muted: var(--qui-fg-muted);
  --color-fg-subtle: var(--qui-fg-subtle);
  --color-border: var(--qui-border);
  --color-border-strong: var(--qui-border-strong);
  --color-primary: var(--qui-primary);
  --color-primary-hover: var(--qui-primary-hover);
  --color-primary-fg: var(--qui-primary-fg);
  --color-danger: var(--qui-danger);
  --color-danger-fg: var(--qui-danger-fg);
  --color-success: var(--qui-success);
  --color-warning: var(--qui-warning);
  --color-info: var(--qui-info);
  --color-ring: var(--qui-ring);
  --color-backdrop: var(--qui-backdrop);
  --shadow-float: var(--qui-shadow-float);
  --radius-control: 0.5rem;
  --radius-float: 0.75rem;
}

/*
 * Motion utilities. Components never hand-roll transitions; they pick one of these.
 * All are CSS transitions (interruptible mid-flight), honour Base UI's data-instant,
 * skip animation when the user is driving with the keyboard, and keep only the
 * fade under prefers-reduced-motion or an app-level <html data-motion="reduced">.
 */

/* Popovers, menus, tooltips: scale out of the trigger. */
@utility motion-pop {
  transform-origin: var(--transform-origin, center);
  transition-property: opacity, scale;
  transition-duration: var(--qui-duration-base);
  transition-timing-function: var(--qui-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
    scale: var(--qui-pop-scale);
  }
  &[data-ending-style] {
    transition-duration: var(--qui-duration-exit);
  }
  &[data-instant],
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    scale: 1;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      scale: 1;
    }
  }
}

/* Dialogs: a small lift instead of a zoom; large surfaces that scale look sluggish. */
@utility motion-dialog {
  transition-property: opacity, scale, translate;
  transition-duration: var(--qui-duration-slow);
  transition-timing-function: var(--qui-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
    scale: 0.98;
    translate: 0 var(--qui-pop-shift);
  }
  &[data-ending-style] {
    transition-duration: var(--qui-duration-exit);
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    scale: 1;
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      scale: 1;
      translate: 0 0;
    }
  }
}

/*
 * Sheets: slide in from an edge set by --qui-sheet-hidden (e.g. translateX(100%)) and
 * follow the finger while swiping (Base UI Drawer's swipe variables).
 */
@utility motion-sheet {
  transform: translate(var(--drawer-swipe-movement-x, 0px), var(--drawer-swipe-movement-y, 0px));
  transition-property: transform, opacity;
  transition-duration: var(--qui-duration-slow);
  transition-timing-function: var(--qui-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    transform: var(--qui-sheet-hidden);
  }
  &[data-ending-style] {
    transition-duration: var(--qui-duration-exit);
  }
  &[data-swiping] {
    transition-duration: 0ms;
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    transform: none;
    opacity: 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      transform: none;
      opacity: 0;
    }
  }
}

/* Backdrops and anything that only needs opacity. */
@utility motion-fade {
  transition-property: opacity;
  transition-duration: var(--qui-duration-base);
  transition-timing-function: var(--qui-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
  }
  &[data-ending-style] {
    transition-duration: var(--qui-duration-exit);
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
}

/* Hover and press feedback. Paint-only properties so it can never shift layout. */
@utility motion-control {
  transition-property: color, background-color, border-color, box-shadow, scale, translate;
  transition-duration: var(--qui-duration-fast);
  transition-timing-function: var(--qui-ease-out);
}

/*
 * Label swaps inside a control (confirm steps, status text). Stack every state in one
 * grid cell so the control keeps the width of its longest label, then mark the
 * inactive ones data-swap="out". A quick crossfade with a hint of lift.
 */
@utility motion-swap {
  transition-property: opacity, translate;
  transition-duration: var(--qui-duration-fast);
  transition-timing-function: var(--qui-ease-out);
  &[data-swap="out"] {
    opacity: 0;
    translate: 0 0.3em;
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-swap="out"] {
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-swap="out"] {
      translate: 0 0;
    }
  }
}

/* Inline messages under a control (field errors, hints): a short drop from the control. */
@utility motion-message {
  transition-property: opacity, translate;
  transition-duration: var(--qui-duration-fast);
  transition-timing-function: var(--qui-ease-out);
  &[data-starting-style],
  &[data-ending-style] {
    opacity: 0;
    translate: 0 -0.25em;
  }
  &[data-ending-style] {
    transition-duration: var(--qui-duration-exit);
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style],
  :root[data-motion="reduced"] &[data-ending-style] {
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style],
    &[data-ending-style] {
      translate: 0 0;
    }
  }
}

/*
 * Parts that slide between two places (switch thumbs). Moves with translate on the base
 * duration; from the keyboard it is instant, and under reduced motion it jumps while the
 * colour still fades, so the change stays easy to follow.
 */
@utility motion-thumb {
  transition-property: translate, background-color;
  transition-duration: var(--qui-duration-base);
  transition-timing-function: var(--qui-ease-out);
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] & {
    transition-property: background-color;
  }
  @media (prefers-reduced-motion: reduce) {
    transition-property: background-color;
  }
}

/*
 * A marker that slides to the chosen item (the tab underline, a segmented control's raised
 * background). Width and height animate too, which is safe here: the marker is absolutely
 * positioned, so it never moves anything around it. Instant from the keyboard; under reduced
 * motion it jumps.
 */
@utility motion-indicator {
  transition-property: translate, width, height;
  transition-duration: var(--qui-duration-base);
  transition-timing-function: var(--qui-ease-out);
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] & {
    transition-duration: 0ms;
  }
  @media (prefers-reduced-motion: reduce) {
    transition-duration: 0ms;
  }
}

/*
 * Content that swaps in place (tab panels): a quick fade with a 4px shift from the side the
 * user moved towards, set by Base UI's data-activation-direction. Reduced motion keeps the fade.
 */
@utility motion-panel {
  transition-property: opacity, translate;
  transition-duration: var(--qui-duration-base);
  transition-timing-function: var(--qui-ease-out);
  &[data-starting-style] {
    opacity: 0;
  }
  &[data-starting-style][data-activation-direction="right"] {
    translate: 4px 0;
  }
  &[data-starting-style][data-activation-direction="left"] {
    translate: -4px 0;
  }
  &[data-starting-style][data-activation-direction="down"] {
    translate: 0 4px;
  }
  &[data-starting-style][data-activation-direction="up"] {
    translate: 0 -4px;
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] &[data-starting-style] {
    translate: 0 0;
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-starting-style] {
      translate: 0 0;
    }
  }
}

/*
 * Toasts: transform and height carry the slide in, the deck and the fan-out on hover; height
 * may animate because toasts are absolutely positioned. While a toast is being swiped it
 * follows the finger with no transition. Reduced motion keeps only the fade; the stack still
 * lays out the same, it just does not move between states.
 */
@utility motion-toast {
  transition-property: opacity, transform, scale, height;
  transition-duration: var(--qui-duration-slow);
  transition-timing-function: var(--qui-ease-out);
  /* 160ms, not the usual exit: toasts are closed while you look at them, and 110ms reads as a blink. */
  &[data-ending-style] {
    transition-duration: var(--qui-duration-base);
  }
  /* Fades with drag distance (60% at the 40px commit point), so you can see a release will dismiss. */
  &[data-swiping] {
    transition-property: opacity;
    opacity: max(0.3, 1 - tan(atan2(max(var(--toast-swipe-movement-x), var(--toast-swipe-movement-y)), 100px)));
  }
  /* The icon stamps in after the toast lands, and again when loading turns into a result. */
  & [data-toast-icon] {
    transition-property: opacity, scale;
    transition-duration: var(--qui-duration-base);
    transition-timing-function: var(--qui-ease-out);
    transition-delay: 60ms;
    @starting-style {
      opacity: 0;
      scale: 0.5;
    }
  }
  /* The bar eases between updates, so progress reported in bursts still moves smoothly. */
  & [data-toast-progress] {
    transition: transform var(--qui-duration-slow) var(--qui-ease-out);
  }
  :root[data-input="keyboard"] & [data-toast-icon] {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] & {
    transition-property: opacity;
    & [data-toast-progress] {
      transition: none;
    }
    & [data-toast-icon] {
      transition-property: opacity;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    transition-property: opacity;
    & [data-toast-progress] {
      transition: none;
    }
    & [data-toast-icon] {
      transition-property: opacity;
    }
  }
}

/* A small mark that pops in when it appears or changes, like a count. Key it by its value. */
@utility motion-stamp {
  transition-property: opacity, scale;
  transition-duration: var(--qui-duration-base);
  transition-timing-function: var(--qui-ease-out);
  @starting-style {
    opacity: 0;
    scale: 0.5;
  }
  :root[data-input="keyboard"] & {
    transition-duration: 0ms;
  }
  :root[data-motion="reduced"] & {
    transition-property: opacity;
  }
  @media (prefers-reduced-motion: reduce) {
    transition-property: opacity;
  }
}

/*
 * Notification badges. A real arrival is choreographed, all in scale, translate and opacity:
 * the avatar dips as if something landed (motion-notify-host); the badge squeezes out of the
 * avatar like a drop of liquid while two droplets fall back in behind it; it lands with a small
 * splash and one ripple; then the number pops in and a sheen passes over. A count going up makes
 * the badge gulp and the number roll. A notification is not an answer to input and is rare, so
 * this is a deliberate expressive moment: the whole arrival takes about 650ms, past
 * --qui-duration-slow. Reduced motion keeps only the fades. The badge's resting offset is
 * --bx/--by, which the keyframes start from.
 */
@keyframes qui-notify-in {
  0% {
    opacity: 0;
    scale: 0.25 0.25;
    translate: calc(var(--bx) - 70%) calc(var(--by) + 70%);
  }
  35% {
    opacity: 1;
    scale: 1.15 0.88;
    translate: calc(var(--bx) + 10%) calc(var(--by) - 10%);
  }
  65% {
    scale: 0.9 1.1;
    translate: var(--bx) var(--by);
  }
  82% {
    scale: 1.04 0.97;
  }
  100% {
    scale: 1 1;
    translate: var(--bx) var(--by);
  }
}
@keyframes qui-notify-out {
  to {
    opacity: 0;
    scale: 0.3 0.3;
    translate: calc(var(--bx) - 50%) calc(var(--by) + 50%);
  }
}
@keyframes qui-notify-receive {
  0% {
    scale: 1;
  }
  22% {
    scale: 0.955;
  }
  58% {
    scale: 1.02;
  }
  100% {
    scale: 1;
  }
}
@keyframes qui-notify-trail {
  from {
    opacity: 1;
    scale: 1;
    translate: 0 0;
  }
  to {
    opacity: 0;
    scale: 0;
    translate: -70% 70%;
  }
}
@keyframes qui-notify-halo {
  from {
    opacity: 0.35;
    scale: 1;
  }
  to {
    opacity: 0;
    scale: 2;
  }
}
@keyframes qui-notify-splash {
  0% {
    opacity: 0;
    scale: 1;
    translate: 0 0;
  }
  20% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    scale: 0.3;
    translate: var(--sx) var(--sy);
  }
}
@keyframes qui-notify-gulp {
  0% {
    scale: 1 1;
  }
  35% {
    scale: 1.18 0.86;
  }
  65% {
    scale: 0.94 1.06;
  }
  100% {
    scale: 1 1;
  }
}
@keyframes qui-notify-pop {
  0% {
    opacity: 0;
    scale: 0.4;
  }
  70% {
    opacity: 1;
    scale: 1.12;
  }
  100% {
    scale: 1;
  }
}
@keyframes qui-notify-sheen {
  to {
    translate: 200% 0;
  }
}
@keyframes qui-notify-fade {
  from {
    opacity: 0;
  }
}
@keyframes qui-roll-in-up {
  from {
    opacity: 0;
    translate: 0 75%;
  }
}
@keyframes qui-roll-in-down {
  from {
    opacity: 0;
    translate: 0 -75%;
  }
}
@keyframes qui-roll-out-up {
  to {
    opacity: 0;
    translate: 0 -75%;
  }
}
@keyframes qui-roll-out-down {
  to {
    opacity: 0;
    translate: 0 75%;
  }
}
@utility motion-notify {
  &[data-arrive] {
    animation: qui-notify-in 380ms var(--qui-ease-out) both;
  }
  &[data-leaving] {
    animation: qui-notify-out var(--qui-duration-exit) var(--qui-ease-out) forwards;
  }
  & [data-trail="1"] {
    animation: qui-notify-trail 260ms var(--qui-ease-out) 30ms both;
  }
  & [data-trail="2"] {
    animation: qui-notify-trail 240ms var(--qui-ease-out) 70ms both;
  }
  & [data-halo] {
    animation: qui-notify-halo 600ms var(--qui-ease-out) 120ms both;
  }
  & [data-splash] {
    animation: qui-notify-splash 420ms var(--qui-ease-out) 170ms both;
  }
  & [data-gulp] {
    animation: qui-notify-gulp 360ms var(--qui-ease-out);
  }
  & [data-sheen] {
    animation: qui-notify-sheen 320ms var(--qui-ease-in-out) 280ms both;
  }
  & [data-roll="pop"] {
    animation: qui-notify-pop 260ms var(--qui-ease-out) 160ms both;
  }
  & [data-roll="in"][data-dir="up"] {
    animation: qui-roll-in-up var(--qui-duration-slow) var(--qui-ease-out) both;
  }
  & [data-roll="in"][data-dir="down"] {
    animation: qui-roll-in-down var(--qui-duration-slow) var(--qui-ease-out) both;
  }
  & [data-roll="out"][data-dir="up"] {
    animation: qui-roll-out-up var(--qui-duration-slow) var(--qui-ease-out) forwards;
  }
  & [data-roll="out"][data-dir="down"] {
    animation: qui-roll-out-down var(--qui-duration-slow) var(--qui-ease-out) forwards;
  }
  :root[data-motion="reduced"] & {
    &[data-arrive],
    & [data-roll] {
      animation: qui-notify-fade var(--qui-duration-base) var(--qui-ease-out) both;
    }
    & :is([data-trail], [data-halo], [data-splash], [data-sheen]) {
      display: none;
    }
    & [data-gulp] {
      animation: none;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    &[data-arrive],
    & [data-roll] {
      animation: qui-notify-fade var(--qui-duration-base) var(--qui-ease-out) both;
    }
    & :is([data-trail], [data-halo], [data-splash], [data-sheen]) {
      display: none;
    }
    & [data-gulp] {
      animation: none;
    }
  }
}
/* On the avatar: a small dip and rebound when a notification lands on it. */
@utility motion-notify-host {
  &:has(> [data-notify][data-arriving]) {
    animation: qui-notify-receive 340ms var(--qui-ease-out);
  }
  :root[data-motion="reduced"] & {
    animation: none;
  }
  @media (prefers-reduced-motion: reduce) {
    animation: none;
  }
}

/* Shared focus ring, keyboard focus only. */
@utility focus-ring {
  outline: 2px solid transparent;
  outline-offset: 2px;
  &:focus-visible {
    outline-color: var(--qui-ring);
  }
}

/*
 * Scroll edges: a soft shadow on a sticky part that shows only while content is under it, driven
 * by the scroll position itself (no JS, no listeners). Put one on a pseudo-element of the sticky
 * part. Browsers without scroll timelines show no shadow, which is the quiet default anyway.
 */
@keyframes qui-edge-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes qui-edge-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
/* Under a sticky top: appears over the first 1rem of scrolling down. */
@utility scroll-edge-top {
  opacity: 0;
  @supports (animation-timeline: scroll()) {
    animation: qui-edge-in linear both;
    animation-timeline: scroll(nearest block);
    animation-range: 0 1rem;
  }
}
/* Above a sticky bottom: shows while there is more below, fades over the last 1rem. */
@utility scroll-edge-bottom {
  opacity: 0;
  @supports (animation-timeline: scroll()) {
    animation: qui-edge-out linear both;
    animation-timeline: scroll(nearest block);
    animation-range: calc(100% - 1rem) 100%;
  }
}
/* Beside a sticky start column: appears once scrolled sideways. */
@utility scroll-edge-start {
  opacity: 0;
  @supports (animation-timeline: scroll()) {
    animation: qui-edge-in linear both;
    animation-timeline: scroll(nearest inline);
    animation-range: 0 1rem;
  }
}

/*
 * Loading placeholders. They hold their space at once but only fade in after 150ms, so a fast
 * load never flashes them; a slow, faint sweep says the work is still going. The sweep moves a
 * pseudo-element with translate, and stops under reduced motion.
 */
@keyframes qui-skeleton-in {
  from {
    opacity: 0;
  }
}
@keyframes qui-skeleton-sweep {
  from {
    translate: -100% 0;
  }
  to {
    translate: 100% 0;
  }
}
@utility skeleton {
  position: relative;
  overflow: hidden;
  background-color: var(--qui-skeleton);
  animation: qui-skeleton-in var(--qui-duration-slow) var(--qui-ease-out) 150ms both;
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    translate: -100% 0;
    background: linear-gradient(90deg, transparent, var(--qui-skeleton-sweep), transparent);
    animation: qui-skeleton-sweep 1.8s var(--qui-ease-in-out) 0.4s infinite;
  }
  :root[data-motion="reduced"] &::after {
    animation: none;
  }
  @media (prefers-reduced-motion: reduce) {
    &::after {
      animation: none;
    }
  }
}

/* Numbers in data UIs should not jitter while they update. */
@utility nums {
  font-variant-numeric: tabular-nums;
}
